"use client";

import * as React from "react";
import { Tabs as TabsPrimitive } from "@base-ui/react/tabs";

import { cn } from "@/lib/utils";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

const Tabs = TabsPrimitive.Root;

/**
 * Bold retail TabsList: a row of labels 1.5rem apart, standing on a soft
 * inset hairline. Nothing fills behind the active tab.
 */
const TabsList = React.forwardRef<
  HTMLDivElement,
  WithClassName<TabsPrimitive.List.Props>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.List
    ref={ref}
    data-slot="tabs-list"
    className={cn(
      "inline-flex items-center gap-6 text-muted-foreground shadow-(--shadow-line)",
      className,
    )}
    {...props}
  />
));
TabsList.displayName = "TabsList";

/**
 * Bold retail TabsTrigger: a 1rem medium label in grey that turns
 * near-black on hover. The active tab reads near-black with a 0.125rem
 * black bar along its foot.
 */
const TabsTrigger = React.forwardRef<
  HTMLButtonElement,
  WithClassName<TabsPrimitive.Tab.Props>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.Tab
    ref={ref}
    data-slot="tabs-trigger"
    className={cn(
      "relative inline-flex h-11 shrink-0 items-center justify-center gap-2 whitespace-nowrap",
      "text-base font-medium text-muted-foreground",
      "transition-colors duration-fast ease-out hover:text-foreground",
      "after:absolute after:inset-x-0 after:bottom-0 after:h-0.5 after:bg-primary",
      "after:opacity-0 after:transition-opacity after:duration-fast after:ease-out",
      "data-[active]:text-foreground data-[active]:after:opacity-100",
      "outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring",
      "data-[disabled]:cursor-not-allowed data-[disabled]:text-(--foreground-disabled)",
      "[&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
      className,
    )}
    {...props}
  />
));
TabsTrigger.displayName = "TabsTrigger";

/** Bold retail TabsContent: the active panel, set 1.5rem below the tab row. */
const TabsContent = React.forwardRef<
  HTMLDivElement,
  WithClassName<TabsPrimitive.Panel.Props>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.Panel
    ref={ref}
    data-slot="tabs-content"
    className={cn(
      "mt-6 outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
      className,
    )}
    {...props}
  />
));
TabsContent.displayName = "TabsContent";

export { Tabs, TabsList, TabsTrigger, TabsContent };
